'use client';

import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type KeyboardEvent,
  type MouseEvent,
  type ReactNode,
} from 'react';
import { focusMenuItem, handleMenuKeys } from './menu-keys';
import { useDismiss } from './use-dismiss';
import './context-menu.css';

export interface ContextMenuItem {
  id: string;
  label: string;
}

export interface ContextMenuProps {
  items: ContextMenuItem[];
  onSelect: (id: string) => void;
  /** Accessible name of the area the menu belongs to. */
  label: string;
  children: ReactNode;
  className?: string;
}

const useIsomorphicLayoutEffect =
  typeof window === 'undefined' ? useEffect : useLayoutEffect;

/**
 * Right-click (or long-press on some devices) opens a menu at the pointer,
 * kept inside the area. Keyboard users press Shift+F10 or the Menu key on
 * the focused area; a visible "Actions" button opens it on touch.
 */
export function ContextMenu({
  items,
  onSelect,
  label,
  children,
  className = '',
}: ContextMenuProps) {
  const area = useRef<HTMLDivElement>(null);
  const menu = useRef<HTMLDivElement>(null);
  const button = useRef<HTMLButtonElement>(null);
  const returnTo = useRef<HTMLElement | null>(null);
  const [at, setAt] = useState<{ x: number; y: number } | null>(null);
  const [pos, setPos] = useState({ x: 0, y: 0 });

  useIsomorphicLayoutEffect(() => {
    if (!at || !area.current || !menu.current) return;
    const w = area.current.clientWidth;
    const h = area.current.clientHeight;
    setPos({
      x: Math.max(4, Math.min(at.x, w - menu.current.offsetWidth - 4)),
      y: Math.max(4, Math.min(at.y, h - menu.current.offsetHeight - 4)),
    });
    focusMenuItem(menu.current);
  }, [at]);

  const openAt = (x: number, y: number, from: HTMLElement | null) => {
    returnTo.current = from;
    setAt({ x, y });
  };
  const close = (refocus: boolean) => {
    setAt(null);
    if (refocus) returnTo.current?.focus();
  };
  useDismiss(at !== null, [menu], (reason) => close(reason === 'escape'));

  const onContextMenu = (event: MouseEvent<HTMLDivElement>) => {
    event.preventDefault();
    const rect = event.currentTarget.getBoundingClientRect();
    openAt(event.clientX - rect.left, event.clientY - rect.top, area.current);
  };
  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.target !== area.current) return;
    if (
      event.key === 'ContextMenu' ||
      (event.key === 'F10' && event.shiftKey)
    ) {
      event.preventDefault();
      openAt(16, 16, area.current);
    }
  };

  return (
    <div
      ref={area}
      className={`mg-ctx ${className}`}
      tabIndex={0}
      role='group'
      aria-label={`${label}. Press Shift+F10 for actions.`}
      onContextMenu={onContextMenu}
      onKeyDown={onKeyDown}
    >
      {children}
      <button
        ref={button}
        type='button'
        className='mg-ctx__button'
        aria-haspopup='menu'
        aria-expanded={at !== null}
        onClick={(event) => {
          const rect = area.current!.getBoundingClientRect();
          const b = event.currentTarget.getBoundingClientRect();
          openAt(b.left - rect.left, b.bottom - rect.top + 4, button.current);
        }}
      >
        Actions
      </button>
      {at ? (
        <div
          ref={menu}
          role='menu'
          aria-label={`${label} actions`}
          className='mg-ctx__menu'
          style={{ transform: `translate(${pos.x}px, ${pos.y}px)` }}
          onKeyDown={(event) => {
            if (event.key === 'Tab') close(false);
            else handleMenuKeys(event, menu.current);
          }}
        >
          {items.map((item) => (
            <button
              key={item.id}
              type='button'
              role='menuitem'
              tabIndex={-1}
              onClick={() => {
                close(true);
                onSelect(item.id);
              }}
            >
              {item.label}
            </button>
          ))}
        </div>
      ) : null}
    </div>
  );
}

.mg-ctx {
  position: relative;
  min-height: 170px;
  padding: 14px;
  overflow: hidden;
  border: 1px dashed #474747;
  border-radius: 12px;
  background: #121212;
  color: var(--mg-text, #ffffff);
  -webkit-touch-callout: none;
}

.mg-ctx:focus-visible {
  outline: 3px solid var(--mg-accent-text, #dce9f7);
  outline-offset: 2px;
}

.mg-ctx__button {
  position: absolute;
  right: 10px;
  bottom: 10px;
  min-height: 40px;
  padding: 0 12px;
  border: 1px solid var(--mg-line-strong, #474747);
  border-radius: 8px;
  background: #121212;
  color: inherit;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.mg-ctx__button:focus-visible {
  outline: 2px solid var(--mg-accent-text, #dce9f7);
  outline-offset: 2px;
}

.mg-ctx__menu {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 10;
  display: grid;
  min-width: 160px;
  padding: 5px;
  border: 1px solid var(--mg-line, #303030);
  border-radius: 10px;
  background: #121212;
  box-shadow: 0 16px 30px -14px rgba(0, 0, 0, 0.5);
}

.mg-ctx__menu > * {
  animation: mg-ctx-in 160ms ease-out both;
}

.mg-ctx__menu button {
  min-height: 38px;
  padding: 0 10px;
  border: 0;
  border-radius: 6px;
  background: none;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.mg-ctx__menu button:hover,
.mg-ctx__menu button:focus {
  outline: none;
  background: #1e2329;
}

.mg-ctx__menu button:focus-visible {
  box-shadow: inset 0 0 0 2px var(--mg-accent-text, #dce9f7);
}

@keyframes mg-ctx-in {
  from {
    opacity: 0;
    transform: translateY(-3px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-ctx__menu > * {
    animation: none;
  }
}

const ITEM =
  '[role="menuitem"]:not([aria-disabled="true"]), [role="menuitemradio"], [role="menuitemcheckbox"]';

function items(menu: HTMLElement) {
  return Array.from(menu.querySelectorAll<HTMLElement>(ITEM)).filter(
    (item) => item.closest('[role="menu"]') === menu
  );
}

/** Moves focus to the first (or last) item of `menu`. */
export function focusMenuItem(
  menu: HTMLElement | null,
  which: 'first' | 'last' = 'first'
) {
  if (!menu) return;
  const list = items(menu);
  list[which === 'first' ? 0 : list.length - 1]?.focus();
}

/**
 * Arrow, Home and End navigation between the items of `menu`. Call it from
 * the menu's keydown handler. Returns true when the key was handled.
 */
export function handleMenuKeys(
  event: { key: string; preventDefault(): void },
  menu: HTMLElement | null
): boolean {
  if (!menu) return false;
  const list = items(menu);
  if (list.length === 0) return false;
  const index = list.indexOf(document.activeElement as HTMLElement);
  let next: number;
  switch (event.key) {
    case 'ArrowDown':
      next = (index + 1) % list.length;
      break;
    case 'ArrowUp':
      next = index <= 0 ? list.length - 1 : index - 1;
      break;
    case 'Home':
      next = 0;
      break;
    case 'End':
      next = list.length - 1;
      break;
    default:
      return false;
  }
  event.preventDefault();
  list[next].focus();
  return true;
}

'use client';

import { useEffect, useRef, type RefObject } from 'react';

export type DismissReason = 'escape' | 'outside';

/**
 * While `active`, calls `onDismiss` when Escape is pressed or when a pointer
 * goes down outside every element in `refs`. Decide where focus goes in
 * `onDismiss`: back to the trigger after Escape, left alone after an
 * outside press.
 */
export function useDismiss(
  active: boolean,
  refs: RefObject<HTMLElement | null>[],
  onDismiss: (reason: DismissReason) => void
) {
  const callback = useRef(onDismiss);
  callback.current = onDismiss;
  const inside = useRef(refs);
  inside.current = refs;

  useEffect(() => {
    if (!active) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Escape') return;
      event.preventDefault();
      callback.current('escape');
    };
    const onPointerDown = (event: PointerEvent) => {
      const target = event.target as Node;
      if (inside.current.some((ref) => ref.current?.contains(target))) return;
      callback.current('outside');
    };
    document.addEventListener('keydown', onKeyDown);
    document.addEventListener('pointerdown', onPointerDown);
    return () => {
      document.removeEventListener('keydown', onKeyDown);
      document.removeEventListener('pointerdown', onPointerDown);
    };
  }, [active]);
}
